            if tasks.get(dest_index).and_then(|t| t["status"].as_str()) == Some("Failed") { failed = true; break; }
            if tasks.get(dest_index).and_then(|t| t["status"].as_str()) == Some("Completed") { panic!("competing destination was overwritten"); }
